using System; using System.Diagnostics; using System.Net; using System.Threading.Tasks; class Program { static void Main() { try { var timer = Stopwatch.StartNew(); var req = WebRequest.Create("http://speedtest.tele2.net/upload.php"); req.Method = "POST"; req.Timeout = 10000; var data = new byte[2 * 1024 * 1024]; req.ContentLength = data.Length; using (var stream = req.GetRequestStream()) { stream.Write(data, 0, data.Length); } var resp = req.GetResponse(); timer.Stop(); Console.WriteLine("Upload: " + ((data.Length * 8.0 / 1000000.0) / timer.Elapsed.TotalSeconds)); } catch (Exception ex) { Console.WriteLine("UL ERR: " + ex.Message); } } }
